-- Jeu des CREANCES du lot 12 (plan-676a4b19) : « Ajouter une créance » (PROC_ADDCREANCE), « Intégrer des créances »
-- (PROC_INTEGCREANCE) et « Modifier une créance » (PROC_MODCREANCE) lisent les memes tables : leurs lignes sont TOUTES ici
-- (PROC_INTEGCREANCE.sql et PROC_MODCREANCE.sql n'en ajoutent pas). Identifiants 22020xx (PC), 22021xx (creances transitoires),
-- 22022xx (creances PC), 22023xx (creanciers PC), 22024xx (demande du verrou). Types : ceux de RIG_DEV (SSDT
-- RigDatabase\dbo\Tables\CREANCE_TRANSITOIRE.sql, CREANCE_PC.sql, CREANCIER_PC.sql, PROCEDURE_COLLECTIVE.sql), colonnes lues et
-- ecrites ; cles sans IDENTITY (GesteEnCours.InsererAsync prend MAX + 1), les DEFAULT de RIG_DEV donnes par l'ecrivain.
IF OBJECT_ID(N'v2.CREANCE_TRANSITOIRE') IS NULL
    CREATE TABLE v2.CREANCE_TRANSITOIRE (CRTRA_ID_CRTRA int NOT NULL PRIMARY KEY, CRTRA_DATE_CREATION datetime NOT NULL,
        CRTRA_DATE_INSERTION_RIG datetime NULL, CRTRA_NATURE_ERREUR varchar(100) NULL, CRTRA_NUM_PC varchar(10) NULL,
        CRTRA_CIVILITE_CR varchar(7) NULL, CRTRA_NOM_CR varchar(512) NULL, CRTRA_LIGNE_ADRESSE_CR varchar(255) NULL, CRTRA_CP_CR varchar(32) NULL,
        CRTRA_VILLE_CR varchar(255) NULL, CRTRA_REFERENCES_CR varchar(32) NULL, CRTRA_DECLARE_PRIVI_ECHU money NULL,
        CRTRA_DECLARE_PRIVI_NONECHU money NULL, CRTRA_DECLARE_CHIRO_ECHU money NULL, CRTRA_DECLARE_CHIRO_NONECHU money NULL,
        CRTRA_ADMIS_PRIVI_ECHU money NULL, CRTRA_ADMIS_PRIVI_NONECHU money NULL, CRTRA_ADMIS_CHIRO_ECHU money NULL,
        CRTRA_ADMIS_CHIRO_NONECHU money NULL, CRTRA_NATURE_CREANCE_ADM varchar(128) NULL, CRTRA_ADMIS_SUPER_PRIVI_ECHU money NULL,
        CRTRA_ADMIS_PRIVI_PROVISIONNEL money NULL, CRTRA_ADMIS_CHIRO_PROVISIONNEL money NULL, CRTRA_REJETE money NULL,
        CRTRA_OBSERVATIONS varchar(1000) NULL, CRTRA_ETAT_CREANCE varchar(1) NULL, CRTRA_NOM_DEBITEUR varchar(100) NULL,
        CRTRA_NOM_FICHIER varchar(80) NULL, CRTRA_DATE_ACTE datetime NULL, CRTRA_CREANCE_IS_CONTESTE bit NULL, CRTRA_ID_ADRBS_CR int NULL,
        CRTRA_ID_MNDTR int NULL, CRTRA_SIREN varchar(9) NULL, CRTRA_DEFAUT_REPONSE bit NULL);
IF OBJECT_ID(N'v2.CREANCIER_PC') IS NULL
    CREATE TABLE v2.CREANCIER_PC (CREPC_ID_CREPC int NOT NULL PRIMARY KEY, CREPC_ID_MNDTR int NULL, CREPC_ID_ADRBS int NULL,
        CREPC_SUBROGE bit NOT NULL, CREPC_CIVILITE varchar(7) NULL, CREPC_NOM varchar(512) NULL, CREPC_REFERENCES varchar(32) NULL,
        CREPC_MODE_PRESENTATION varchar(3) NULL, CREPC_SIREN varchar(9) NULL);
IF OBJECT_ID(N'v2.CREANCE_PC') IS NULL
    CREATE TABLE v2.CREANCE_PC (CRNPC_ID_CRNPC int NOT NULL PRIMARY KEY, CRNPC_ID_PRCLL int NOT NULL, CRNPC_NUM_ORDRE smallint NOT NULL,
        CRNPC_ID_CREPC int NULL, CRNPC_MONNAIE varchar(3) NOT NULL, CRNPC_NUM_DEPOT varchar(10) NULL, CRNPC_DECLARE_PRIVI_ECHU money NULL,
        CRNPC_DECLARE_PRIVI_NONECHU money NULL, CRNPC_NATURE_CREANCE varchar(128) NULL, CRNPC_DECLARE_CHIRO_ECHU money NULL,
        CRNPC_DECLARE_CHIRO_NONECHU money NULL, CRNPC_ADMIS_PRIVI_ECHU money NULL, CRNPC_ADMIS_PRIVI_NONECHU money NULL,
        CRNPC_NATURE_CREANCE_ADM varchar(128) NULL, CRNPC_ADMIS_CHIRO_ECHU money NULL, CRNPC_ADMIS_CHIRO_NONECHU money NULL,
        CRNPC_OBSERVATIONS varchar(max) NULL, CRNPC_ETAT_CREANCE varchar(1) NOT NULL, CRNPC_ADMIS_SUPER_PRIVI_ECHU money NULL,
        CRNPC_ADMIS_PRIVI_PROVISIONNEL money NULL, CRNPC_REJETE money NULL, CRNPC_ADMIS_CHIRO_PROVISIONNEL money NULL);
IF OBJECT_ID(N'v2.ETAT_CREANCE') IS NULL
    CREATE TABLE v2.ETAT_CREANCE (R_ETATCREANC_VALEUR varchar(1) NOT NULL PRIMARY KEY, R_ETATCREANC_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.AFFAIRE') IS NULL
    CREATE TABLE v2.AFFAIRE (AFFRE_ID_AFFRE int NOT NULL PRIMARY KEY, AFFRE_ID_UTLST_CREATION int NULL, AFFRE_ID_UTLST_EN_COURS int NULL,
        AFFRE_DATE_CREATION datetime NOT NULL, AFFRE_LIBELLE varchar(70) NULL);
IF OBJECT_ID(N'v2.DOSSIER_DEMANDE') IS NULL
    CREATE TABLE v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM int NOT NULL PRIMARY KEY, DSSDM_ID_DMND int NOT NULL,
        DSSDM_CODE_SEQUENCEUR varchar(20) NOT NULL, DSSDM_VALEUR_SEQUENCEUR varchar(100) NULL);
IF COL_LENGTH('v2.DEMANDE', 'DMND_EN_COURS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_EN_COURS bit NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_ID_AFFRE') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_ID_AFFRE int NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_LES_NUMEROS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_LES_NUMEROS varchar(128) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NUM_INDICATIF') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NUM_INDICATIF varchar(14) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM_UTILISATEUR') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM_UTILISATEUR varchar(100) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUM_PC') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUM_PC varchar(10) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_AFFAIRE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_AFFAIRE varchar(max) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_OUVERTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_OUVERTURE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SAUVEGARDE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SAUVEGARDE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_AFFAIRE_FICHIER') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_AFFAIRE_FICHIER varchar(250) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_ETAT_INFO') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_ETAT_INFO varchar(1) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_COMPTEUR_MAJ') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_COMPTEUR_MAJ smallint NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_MAJ') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_MAJ datetime NULL;

-- Par sp_executesql : les colonnes ajoutees ci-dessus n'existent pas encore quand SQL Server compile le lot.
EXEC sp_executesql N'
INSERT INTO v2.ETAT_CREANCE (R_ETATCREANC_VALEUR, R_ETATCREANC_LIBELLE_ECRAN)
SELECT v.c, v.l FROM (VALUES (''0'', ''Admise''), (''2'', ''Contestée''), (''6'', ''Ordonnance sans débat'')) AS v (c, l)
WHERE NOT EXISTS (SELECT 1 FROM v2.ETAT_CREANCE AS e WHERE e.R_ETATCREANC_VALEUR = v.c);

-- Trois PC : ouverte en 2015 (avis d admission : l admission s y integre), ouverte en 2005 (avant le 15/02/2009 : RIG v2 cree une
-- instance, la V3 refuse), ouverte en 2016 et tenue par une demande en cours (verrou de RIG v2, sequenceur 2P).
SET IDENTITY_INSERT v2.PROCEDURE_COLLECTIVE ON;
INSERT INTO v2.PROCEDURE_COLLECTIVE (PRCLL_ID_PRCLL, PRCLL_NUM_PC, PRCLL_NOM_AFFAIRE, PRCLL_DATE_OUVERTURE, PRCLL_ETAT_INFO, PRCLL_COMPTEUR_MAJ,
    PRCLL_DATE_MAJ) VALUES
    (2202001, ''L12PC0001'', ''PC CREANCES ALPHA'', ''20150310'', ''4'', 3, ''20150310''),
    (2202002, ''L12PC0002'', ''PC CREANCES BETA'', ''20050601'', ''1'', 1, ''20050601''),
    (2202003, ''L12PC0003'', ''PC VERROUILLEE GAMMA'', ''20160104'', ''1'', 1, ''20160104'');
SET IDENTITY_INSERT v2.PROCEDURE_COLLECTIVE OFF;
INSERT INTO v2.DEMANDE (DMND_ID_DMND, DMND_NUM_DEMANDE, DMND_ETAT_DEMANDE, DMND_CODE_PROSS, DMND_DATE_CREATION, DMND_EN_COURS, DMND_NOM_UTILISATEUR)
VALUES (2202401, ''26220000401'', ''S'', ''MODCREA'', DATEADD(HOUR, 8, @aujourdhui), 1, ''VERROU AGENT'');
INSERT INTO v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM, DSSDM_ID_DMND, DSSDM_CODE_SEQUENCEUR, DSSDM_VALEUR_SEQUENCEUR) VALUES (2202451, 2202401, ''2P'', ''2202003'');

-- Deux creances admises : celle de 2202101 (integree), et une de la PC verrouillee.
INSERT INTO v2.CREANCIER_PC (CREPC_ID_CREPC, CREPC_SUBROGE, CREPC_CIVILITE, CREPC_NOM, CREPC_MODE_PRESENTATION, CREPC_SIREN) VALUES
