INSERT INTO v2.CREANCE_PC (CRNPC_ID_CRNPC, CRNPC_ID_PRCLL, CRNPC_NUM_ORDRE, CRNPC_ID_CREPC, CRNPC_MONNAIE, CRNPC_NATURE_CREANCE, CRNPC_ETAT_CREANCE,
    CRNPC_ADMIS_PRIVI_ECHU, CRNPC_ADMIS_CHIRO_ECHU) VALUES
