-- Les creances transitoires.
INSERT INTO v2.CREANCE_TRANSITOIRE (CRTRA_ID_CRTRA, CRTRA_DATE_CREATION, CRTRA_DATE_INSERTION_RIG, CRTRA_NATURE_ERREUR, CRTRA_NUM_PC, CRTRA_CIVILITE_CR,
    CRTRA_NOM_CR, CRTRA_ADMIS_PRIVI_ECHU, CRTRA_ADMIS_CHIRO_ECHU, CRTRA_REJETE, CRTRA_NATURE_CREANCE_ADM, CRTRA_ETAT_CREANCE, CRTRA_DATE_ACTE,
    CRTRA_CREANCE_IS_CONTESTE, CRTRA_DEFAUT_REPONSE, CRTRA_NOM_FICHIER) VALUES
    -- integree il y a 3 jours (sa creance PC est 2202201) : Validee ; ECARTEE de « Intégrer » -- jumeau retenu 2202102 (meme PC)
    (2202101, DATEADD(DAY, -3, @aujourdhui), DATEADD(DAY, -3, @aujourdhui), NULL, ''L12PC0001'', ''SOCIETE'', ''CREANCIER INTEGRE A'', 1000.00, NULL, NULL, NULL, ''0'', NULL, 0, 0, ''AMITEL''),
    -- en attente, admission sur la PC de 2015, nature admise : s integre (PROC_INTEGCREANCE.gestes, bloc 3)
    (2202102, DATEADD(HOUR, 9, DATEADD(DAY, -2, @aujourdhui)), NULL, NULL, ''L12PC0001'', ''SOCIETE'', ''CREANCIER ATTENTE B'', NULL, 250.75, NULL, ''Prêt'', ''0'', NULL, 0, 0, ''AMITEL''),
    -- en erreur : sa PC n existe pas (IntegrationCreances.cs:110)
