    -- une ligne de fichier vide (ni PC, ni creancier, ni montant) : AFaire
    (2202107, DATEADD(DAY, -4, @aujourdhui), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, ''CABINET12'');
',
